### Step 4: Add component_members_with_line_count DB method

In `src/db/components.rs`, after `component_file_ids` (~line 314):

```rust
pub fn component_members_with_line_count(&self) -> Result<Vec<(String, i64, i64)>> {
    let conn = self.conn.lock();
    let mut stmt = conn.prepare(
        \"SELECT cm.component_id, cm.file_id, f.line_count
         FROM component_membership cm
         JOIN files f ON f.id = cm.file_id
         JOIN components c ON c.id = cm.component_id
         WHERE c.dissolved_at IS NULL\"
    )?;
    let rows = stmt.query_map([], |row| {
        Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?, row.get::<_, i64>(2)?))
    })?.collect::<rusqlite::Result<Vec<_>>>()?;
    Ok(rows)
}
```

### Step 5: Rewrite file_health MCP tool

Rewrite `handle_with_freshness` in `src/tools/file_health.rs`. The old `FileScores` and `compute_file_scores` stay (pipeline.rs still uses them). New flow:

```rust
pub fn handle_with_freshness(
    db: &Db, path: Option<&str>, limit: Option<i64>,
    mode: Option<&str>, workspace_root: Option<&Path>,
) -> Result<serde_json::Value> {
    let limit = limit.unwrap_or(20) as usize;
    let mode = mode.unwrap_or(\"actionable\");

    // 1. Get all findings with waiver status; exclude waived findings
    let all_findings_waivered = db.get_health_findings_with_waiver_status()?;
    let active_findings: Vec<HealthFindingRow> = all_findings_waivered
        .into_iter()
        .filter(|(_, waived)| !waived)
        .map(|(f, _)| f)
        .collect();

    // 2. Build file_id → path lookup from all_files()
    let files = db.all_files()?;
    let file_map: HashMap<i64, &FileRow> = files.iter().map(|f| (f.id, f)).collect();

    // 3. Group findings by file_id
    let mut by_file: HashMap<i64, Vec<&HealthFindingRow>> = HashMap::new();
    for f in &active_findings {
        by_file.entry(f.file_id).or_default().push(f);
    }

    // 4. If path filter, restrict to matching file
    // 5. For each file with findings, compute score via score_file()
    //    Files with no findings get score 10.0
    // 6. If mode == \"actionable\", only include files with score < 10.0
    // 7. Sort by score ascending, truncate to limit
    // 8. Build JSON output: per-file { path, health_score, category_deductions, findings[] }

    // 9. If no path filter, also compute component scores:
    //    - Get component membership via component_members_with_line_count()
    //    - For each component, collect member file scores and line_counts
    //    - Compute NLOC-weighted average via score_component()
    //    - Include \"components\" array in output

    // 10. Freshness annotation (same pattern as current code)
}
